 impl F{
  fn closed_position(&mut self)->u64{
   let mut e=self.event();e["reviewMaximumQuantity"]=json!(2);e["reviewMaximumPrincipal"]=json!("10.000000");self.reserve(&e).unwrap();let q=self.b().engine().order_records()[0].clone();let id=q["id"].as_u64().unwrap();
   let mut ack=json!({"type":"actual_order_ack","source":"official_sig_api_v1","receiptHash":"c".repeat(64),"orderId":id,"actualOrderId":"901","marketId":"201","exchangeId":"101","side":"YES","action":"buy","price":"0.400000","quantity":2,"receivedAt":iso(6001)});
   self.bank.as_mut().unwrap().accept("actual",1,&ack).unwrap();ack["type"]=json!("actual_fill");ack["fillId"]=json!("701");ack["executedAt"]=json!(iso(6000));ack["fee"]=json!("0.000000");self.bank.as_mut().unwrap().accept("actual",2,&ack).unwrap();
   ack["type"]=json!("actual_order_terminal");ack["status"]=json!("filled");ack["filledQuantity"]=json!(2);ack["fillsComplete"]=json!(true);self.bank.as_mut().unwrap().accept("actual",3,&ack).unwrap();
   self.bank.as_mut().unwrap().accept("retire-planner",1,&json!({"type":"tick","receivedAt":iso(6100)})).unwrap();
   for(i,q)in self.b().engine().order_records().into_iter().filter(|q|q["retired"]==false).enumerate(){self.bank.as_mut().unwrap().accept("cleanup",i as u64+1,&json!({"type":"unsubmitted_intent_retired","source":"moloch_live_dispatcher","orderId":q["id"],"confirmedNetworkAttempts":0,"receiptHash":"e".repeat(64),"deferPlanningForPackage":true,"receivedAt":iso(6200)})).unwrap();}
   id
  }
  fn top_up(&self,id:u64)->Value{let mut e=self.event();e["receivedAt"]=json!(iso(9000));e["processedAt"]=json!(iso(9000));e["reviewMaximumPrincipal"]=json!("1.300000");e["reviewMaximumQuantity"]=json!(10);
   e["sameSideTopUp"]=json!({"version":1,"cohortSha256":"a".repeat(64),"positionsSha256":hash(&self.b().engine().wallet.positions()["101"]),"heldQuantity":2,"heldCost":"0.800000","priorEntries":[{"qid":id,"actualOrderId":"901","filledQuantity":2,"closedDispatchSha256":"f".repeat(64)}],"maximumEntries":2,"maximumTotalQuantity":4});e}
 }
